const SERVICE_AREAS = [
  { slug: 'tallahassee', city: 'Tallahassee', county: 'Leon County', nearest: ['kissimmee', 'davenport'], areas: ['Killearn', 'Midtown', 'FSU / FAMU', 'Southwood', 'Betton Hills', 'Northeast Tallahassee'], roads: 'I-10 · Capital Circle · Apalachee Pkwy · Tennessee St',
    lead: { en: 'UrgiMed covers Tallahassee and Leon County. If you were hurt in a car crash on I-10, Capital Circle or Apalachee Parkway, call us to learn more about your care options — and to stay inside Florida’s 14-day PIP window.', es: 'UrgiMed cubre Tallahassee y el condado de Leon. Si se lesionó en un choque en la I-10, Capital Circle o Apalachee Parkway, llámenos para conocer sus opciones de atención y mantenerse dentro del plazo de 14 días del PIP.' },
    body: { en: 'Tallahassee drivers, students and commuters tell us the same story: a rear-end collision on Capital Circle, a few days of “just stiffness,” then neck pain, headaches or tingling that will not go away. Those are classic delayed symptoms of whiplash, disc injury or nerve compression. Florida’s no-fault law gives you 14 days from the accident to see a doctor for PIP to pay for your care. Call UrgiMed first: our team explains the evaluation options available to Tallahassee patients, arranges your first visit, documents your Emergency Medical Condition and coordinates with your attorney and insurer. No referral is needed, and se habla español.', es: 'Conductores, estudiantes y trabajadores de Tallahassee nos cuentan la misma historia: un choque por alcance en Capital Circle, unos días de “solo rigidez” y luego dolor de cuello, dolores de cabeza u hormigueo que no se van. Son síntomas tardíos clásicos de latigazo cervical, lesión de disco o compresión nerviosa. La ley sin culpa de Florida le da 14 días desde el accidente para ver a un médico y que el PIP pague su atención. Llame primero a UrgiMed: nuestro equipo le explica las opciones de evaluación para pacientes de Tallahassee, organiza su primera visita, documenta su Condición Médica de Emergencia y coordina con su abogado y aseguradora. No necesita referido y se habla español.' },
    title: 'Auto Accident Doctors Serving Tallahassee, FL | Car Accident Injury Care | UrgiMed', desc: 'Injured in a car crash in Tallahassee? UrgiMed covers Leon County: same-day evaluation options within Florida’s 14-day PIP window, no referral needed. Call (407) 807-6262 to learn more.' },
  { slug: 'orlando', city: 'Orlando', county: 'Orange County', nearest: ['kissimmee', 'davenport'], areas: ['Pine Hills', 'East Colonial / Mills 50', 'Curry Ford / Conway', 'Downtown Orlando', 'Ocoee & Winter Garden', 'Lake Nona', 'Apopka', 'Azalea Park'], roads: 'I-4 · SR-408 · SR-417 · Colonial Dr · OBT · Semoran Blvd',
    lead: { en: 'UrgiMed covers Orlando and Orange County, with our Kissimmee clinic minutes away on John Young Parkway. Hurt in a crash on I-4, the 408 or Colonial Drive? Call us to learn more about your care options and get seen within the 14-day PIP window.', es: 'UrgiMed cubre Orlando y el condado de Orange, con nuestra clínica de Kissimmee a minutos por John Young Parkway. ¿Lesionado en un choque en la I-4, la 408 o Colonial Drive? Llámenos para conocer sus opciones de atención y ser atendido dentro del plazo de 14 días del PIP.' },
    body: { en: 'Orlando has some of the busiest crash corridors in Florida: I-4 through downtown, the 408, Colonial Drive, Orange Blossom Trail and Semoran Boulevard. Many of our patients come from Pine Hills, Conway, Azalea Park, Lake Nona and Ocoee, and most arrive with pain that started two or three days after the accident. UrgiMed’s auto accident doctors see Orlando patients the same day: physician exam, X-ray or ultrasound, nerve and range-of-motion testing, and Emergency Medical Condition documentation in one visit, followed by chiropractic care, physical therapy, pain management and orthopedics under one roof. We bill PIP directly, accept Letters of Protection and workers’ comp, help arrange transportation, and coordinate with your attorney. Call to learn more about care options near you.', es: 'Orlando tiene algunos de los corredores con más choques de Florida: la I-4 por el centro, la 408, Colonial Drive, Orange Blossom Trail y Semoran Boulevard. Muchos de nuestros pacientes vienen de Pine Hills, Conway, Azalea Park, Lake Nona y Ocoee, y la mayoría llega con dolor que empezó dos o tres días después del accidente. Los médicos de accidentes de auto de UrgiMed atienden a pacientes de Orlando el mismo día: examen médico, rayos X o ultrasonido, pruebas nerviosas y de rango de movimiento, y documentación de Condición Médica de Emergencia en una sola visita, seguidos de quiropráctica, terapia física, manejo del dolor y ortopedia bajo un mismo techo. Facturamos al PIP directamente, aceptamos Cartas de Protección y compensación laboral, ayudamos con transporte y coordinamos con su abogado. Llame para conocer las opciones de atención cerca de usted.' },
    title: 'Auto Accident Doctors Serving Orlando, FL | Car Accident Injury Clinic | UrgiMed', desc: 'Car accident doctors serving Orlando, Pine Hills, Conway, Lake Nona & Ocoee. Same-day evaluation, X-ray on site, PIP billed directly, no referral needed. Call (407) 807-6262 to learn more.' },
  { slug: 'sebring', city: 'Sebring', county: 'Highlands County', nearest: ['winter-haven', 'davenport'], areas: ['Sebring', 'Avon Park', 'Lake Placid', 'Lorida', 'Highlands County'], roads: 'US-27 · US-98 · SR-66 · Sebring Pkwy',
    lead: { en: 'UrgiMed covers Sebring, Avon Park, Lake Placid and all of Highlands County. After a crash or a fall on US-27 or US-98, call us to learn more about your care options — including transportation help — and keep your 14-day PIP deadline.', es: 'UrgiMed cubre Sebring, Avon Park, Lake Placid y todo el condado de Highlands. Tras un choque o una caída en la US-27 o la US-98, llámenos para conocer sus opciones de atención, incluida ayuda con transporte, y cumplir el plazo de 14 días del PIP.' },
    body: { en: 'Highlands County residents often drive long distances for specialty care, and after a car accident that delay can cost you both your recovery and your PIP benefits. UrgiMed serves Sebring, Avon Park and Lake Placid patients with physician-led accident and injury care: whiplash and soft-tissue injuries, herniated discs, pinched nerves, concussion and post-traumatic headaches, plus slip-and-fall and pedestrian injuries that are common in our retirement communities. Call us first — our team explains your options, helps arrange transportation to your visit when needed, documents your Emergency Medical Condition and works directly with your insurer or attorney. No referral needed; se habla español.', es: 'Los residentes del condado de Highlands suelen conducir largas distancias para recibir atención especializada, y tras un accidente de auto esa demora puede costarle tanto su recuperación como sus beneficios PIP. UrgiMed atiende a pacientes de Sebring, Avon Park y Lake Placid con atención médica de accidentes y lesiones: latigazo cervical y lesiones de tejidos blandos, discos herniados, nervios pinzados, conmoción y dolores de cabeza postraumáticos, además de caídas y accidentes de peatones comunes en nuestras comunidades de retiro. Llámenos primero: nuestro equipo le explica sus opciones, ayuda con transporte a su cita cuando se necesita, documenta su Condición Médica de Emergencia y trabaja directamente con su aseguradora o abogado. Sin referido; se habla español.' },
    title: 'Auto Accident Doctors Serving Sebring & Highlands County, FL | UrgiMed', desc: 'Car accident, slip & fall and work injury care for Sebring, Avon Park and Lake Placid. UrgiMed covers Highlands County — call (407) 807-6262 to learn more about your options within the 14-day PIP window.' },
];

const INJURIES = [
  { slug: 'car-accident', img: 'img/w-car-accident.jpg', priority: true,
    name: { en: 'Car Accident', es: 'Accidente de Auto' },
    h1: { en: 'Auto Accident Doctors in Central Florida — Seen Today', es: 'Médicos de Accidentes de Auto en el Centro de Florida — Atención Hoy' },
    lead: { en: 'Injured in a car crash? Our auto injury doctors see you the same day, with no referral needed. Florida’s 14-day rule: see a doctor within 14 days of the accident or you may lose your PIP benefits — even if your pain has not started yet.', es: '¿Lesionado en un choque? Nuestros médicos de accidentes de auto le atienden el mismo día, sin referido. Regla de 14 días de Florida: vea a un médico dentro de 14 días del accidente o podría perder sus beneficios PIP, aunque el dolor aún no haya comenzado.' },
    conditions: { en: ['Whiplash & soft-tissue strain', 'Neck, back & shoulder pain', 'Herniated or bulging discs', 'Pinched nerve (nerve compression)', 'Concussion & post-traumatic headaches', 'Knee, hip & wrist injuries', 'Numbness, tingling or weakness'], es: ['Latigazo cervical y distensión de tejidos blandos', 'Dolor de cuello, espalda y hombro', 'Discos herniados o abultados', 'Nervio pinzado (compresión nerviosa)', 'Conmoción y dolores de cabeza postraumáticos', 'Lesiones de rodilla, cadera y muñeca', 'Entumecimiento, hormigueo o debilidad'] },
    body: { en: 'Delayed symptoms are common after a car accident: whiplash, disc injuries and nerve compression often show up two or three days later, when adrenaline wears off. Early evaluation by an auto accident doctor catches these injuries before they become chronic — and it protects your claim. Waiting is the most expensive mistake: Florida PIP pays for your care only when treatment starts within 14 days and a doctor certifies an Emergency Medical Condition (EMC). At UrgiMed the same visit covers your exam, X-ray or ultrasound, range-of-motion and nerve testing, and your EMC determination. You leave with a non-surgical treatment plan — chiropractic, physical therapy, pain management and, when needed, image-guided injections — and we send documentation to your insurer and attorney. Drivers, passengers, pedestrians and cyclists are all welcome.', es: 'Los síntomas tardíos son comunes tras un accidente de auto: el latigazo cervical, las lesiones de disco y la compresión nerviosa suelen aparecer dos o tres días después, cuando baja la adrenalina. Una evaluación temprana detecta estas lesiones antes de que se vuelvan crónicas y protege su reclamo. Esperar es el error más costoso: el PIP de Florida paga su atención solo si el tratamiento comienza dentro de 14 días y un médico certifica una Condición Médica de Emergencia (EMC). En UrgiMed la misma visita incluye su examen, rayos X o ultrasonido, pruebas de rango de movimiento y nerviosas, y su determinación EMC. Sale con un plan de tratamiento no quirúrgico (quiropráctica, terapia física, manejo del dolor e inyecciones guiadas por imagen cuando se necesitan) y enviamos la documentación a su aseguradora y abogado. Atendemos conductores, pasajeros, peatones y ciclistas.' },
    title: 'Auto Accident Doctors in Central Florida | Car Accident Injury Clinic | UrgiMed', desc: 'Injured in a car crash? Auto accident doctors in Kissimmee, Davenport & Winter Haven. Same-day evaluation within Florida’s 14-day PIP window, no referral needed, X-ray on site. Call today.' },
  { slug: 'slip-and-fall', img: 'img/w-slip-and-fall.jpg',
    name: { en: 'Slip & Fall', es: 'Resbalón y Caída' },
    h1: { en: 'Slip and Fall Injury Doctor in Florida', es: 'Médico de Lesiones por Caídas en Florida' },
    lead: { en: 'Hurt in a store, parking lot or rental property? We document your injuries the same day — the record your premises-liability claim depends on — and start treatment.', es: '¿Se lastimó en una tienda, estacionamiento o propiedad rentada? Documentamos sus lesiones el mismo día, el registro del que depende su reclamo, y comenzamos el tratamiento.' },
    conditions: { en: ['Hip, wrist & tailbone fractures', 'Knee & ankle sprains', 'Back and neck strain', 'Shoulder tears', 'Head injury & concussion', 'Bruising and soft-tissue injury'], es: ['Fracturas de cadera, muñeca y coxis', 'Esguinces de rodilla y tobillo', 'Tensión de espalda y cuello', 'Desgarros de hombro', 'Lesión en la cabeza y conmoción', 'Moretones y lesiones de tejido blando'] },
    body: { en: 'Falls are the leading cause of injury for adults over 65 and the most disputed type of claim. The key is a medical record created close to the date of the fall, with imaging. UrgiMed provides orthopedic evaluation, X-ray and ultrasound on site, and a rehabilitation plan across chiropractic and physical therapy. We accept most insurance, Letters of Protection and coordinate with your attorney.', es: 'Las caídas son la principal causa de lesión en adultos mayores de 65 años y el tipo de reclamo más disputado. La clave es un expediente médico creado cerca de la fecha de la caída, con imágenes. UrgiMed ofrece evaluación ortopédica, rayos X y ultrasonido en el sitio, y un plan de rehabilitación con quiropráctica y terapia física. Aceptamos la mayoría de seguros y Cartas de Protección.' },
    title: 'Slip and Fall Injury Doctor in Florida | UrgiMed', desc: 'Hurt in a fall? UrgiMed documents your injuries and starts treatment the same day. 4 Central Florida locations, most insurance and attorney liens accepted.' },
  { slug: 'work-injury', img: 'img/w-work-injury.jpg',
    name: { en: 'Work Injury', es: 'Lesión Laboral' },
    h1: { en: 'Workers’ Comp Injury Doctor in Florida', es: 'Médico de Compensación Laboral en Florida' },
    lead: { en: 'Injured on the job? We treat workplace injuries and handle the workers’ compensation paperwork, so you can focus on getting back to work.', es: '¿Se lesionó en el trabajo? Tratamos lesiones laborales y manejamos el papeleo de compensación laboral para que usted se enfoque en recuperarse.' },
    conditions: { en: ['Lifting & back injuries', 'Repetitive strain (wrist, shoulder)', 'Falls from height', 'Machinery & crush injuries', 'Vehicle accidents on the job', 'Slips on wet floors'], es: ['Lesiones de espalda por levantar', 'Esfuerzo repetitivo (muñeca, hombro)', 'Caídas de altura', 'Lesiones por maquinaria', 'Accidentes vehiculares laborales', 'Resbalones en pisos mojados'] },
    body: { en: 'In Florida, your employer or their insurer usually chooses the authorized treating physician — ask for UrgiMed by name. We complete DWC forms, provide work-status notes after every visit, and report progress to the adjuster. Treatment includes orthopedic evaluation, chiropractic, physical therapy, pain management and on-site diagnostics. Se habla español at every clinic.', es: 'En Florida, su empleador o su aseguradora suele elegir al médico tratante autorizado: pida UrgiMed por nombre. Completamos los formularios DWC, entregamos notas de estado laboral en cada visita e informamos el progreso al ajustador. El tratamiento incluye evaluación ortopédica, quiropráctica, terapia física, manejo del dolor y diagnósticos en el sitio. Se habla español en todas las clínicas.' },
    title: 'Workers’ Comp Injury Doctor in Florida | UrgiMed', desc: 'Injured at work? UrgiMed treats workplace injuries and handles workers’ compensation paperwork. Same-day appointments at our Florida clinics.' },
  { slug: 'sports-injury', img: 'img/w-sports-injury.jpg',
    name: { en: 'Sports Injury', es: 'Lesión Deportiva' },
    h1: { en: 'Sports Injury Clinic in Florida — PRP, PT & Ortho', es: 'Clínica de Lesiones Deportivas en Florida — PRP, TF y Ortopedia' },
    lead: { en: 'From weekend warriors to youth athletes: orthopedic evaluation, physical therapy and PRP therapy to get you back to play faster.', es: 'Desde deportistas de fin de semana hasta atletas jóvenes: evaluación ortopédica, terapia física y terapia PRP para volver a jugar más rápido.' },
    conditions: { en: ['ACL & meniscus tears', 'Rotator cuff injuries', 'Ankle sprains', 'Tennis & golfer’s elbow', 'Stress fractures', 'Hamstring & groin strains'], es: ['Desgarros de LCA y menisco', 'Lesiones del manguito rotador', 'Esguinces de tobillo', 'Codo de tenista y golfista', 'Fracturas por estrés', 'Distensiones de isquiotibiales e ingle'] },
    body: { en: 'Our board-certified orthopedic surgeons evaluate you the same week, with X-ray and ultrasound on site. Most sports injuries heal without surgery: we combine physical therapy, chiropractic, cold laser and platelet-rich plasma (PRP) injections that use your own blood to speed tissue repair. When surgery is the right answer, it is performed by our own Mayo Clinic-trained surgeon.', es: 'Nuestros cirujanos ortopédicos certificados le evalúan la misma semana, con rayos X y ultrasonido en el sitio. La mayoría de las lesiones deportivas sanan sin cirugía: combinamos terapia física, quiropráctica, láser frío e inyecciones de plasma rico en plaquetas (PRP) que usan su propia sangre para acelerar la reparación. Cuando la cirugía es la respuesta, la realiza nuestro cirujano formado en Mayo Clinic.' },
    title: 'Sports Injury Clinic in Florida | PRP, PT & Ortho | UrgiMed', desc: 'Sports injury treatment with orthopedic, physical therapy and PRP therapy. Get back to play faster. Clinics across Central and North Florida.' },
];

